def raw_frame(payload, single=True):
    out=bytearray((0xfd2fb528).to_bytes(4,'little')); out+=bytes([0x20, len(payload)&0xff])
    hdr=(0)|(0<<1)|(len(payload)<<3)|(1<<0)
    out+=hdr.to_bytes(3,'little'); out+=payload
    return bytes(out)
complete_frames(raw_frame(b'hello,world')); print('raw block ok')
def rle_frame(n):
    out=bytearray((0xfd2fb528).to_bytes(4,'little')); out+=bytes([0x20, n])
    hdr=(1)|(1<<1)|(n<<3)|(1<<0)
    out+=hdr.to_bytes(3,'little'); out+=bytes([0x41])
    return bytes(out)
